sparql:
PREFIX orkgr: <http://orkg.org/orkg/resource/>
PREFIX orkgc: <http://orkg.org/orkg/class/>
PREFIX orkgp: <http://orkg.org/orkg/predicate/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
# Select paper, title and type of table value/label
SELECT ?paper ?title ?typeOfTable ?typeOfTableLabel
WHERE {
  # Reach the Tabular data description contribution instance
  ?paper orkgp:P31 ?contribution .
  ?contribution a orkgc:C52011 .
  # Paper title
  ?paper rdfs:label ?title .
  # type of table predicate reachable directly or nested under P34063 (one or two levels)
  {
    ?contribution orkgp:P97117 ?typeOfTable .
  } UNION {
    ?contribution orkgp:P34063 ?sub .
    ?sub orkgp:P97117 ?typeOfTable .
  } UNION {
    ?contribution orkgp:P34063 ?sub .
    ?sub orkgp:P34063 ?sub2 .
    ?sub2 orkgp:P97117 ?typeOfTable .
  }
  # Optional label of the type of table resource
  OPTIONAL { ?typeOfTable rdfs:label ?typeOfTableLabel }
}
ORDER BY ?title
